#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;if(!(cin>>n>>m))return 0;vector<vector<int>>g(n+1);for(int i=0,u,v;i<m;i++){cin>>u>>v;g[u].push_back(v);g[v].push_back(u);}for(int i=1;i<=n;i++)sort(g[i].begin(),g[i].end());vector<int>vis(n+1);queue<int>q;q.push(1);vis[1]=1;bool first=true;while(!q.empty()){int u=q.front();q.pop();if(!first)cout<<' ';first=false;cout<<u;for(int v:g[u])if(!vis[v])vis[v]=1,q.push(v);}cout<<endl;return 0;}